namespace MacroStudio.Tests;

/// <summary>Two real game buttons (128x24 px crops from a user's screenshots): the gold RETRY (0/1) button and the gold MODIFIERS button next to it. Same shape, colour and frame; only the label differs.</summary>
static class RealButtons
{
    public const string Retry = "";
    public const string Modifiers = "";
    public static OpenCvSharp.Mat Decode(string b64) => OpenCvSharp.Cv2.ImDecode(Convert.FromBase64String(b64), OpenCvSharp.ImreadModes.Color);

    /// <summary>A strip of the game screen (36 px tall) with LEAVE, MODIFIERS and a GREYED-OUT RETRY (light text on a dark box). LEAVE carries the app's red overlay box.</summary>
    public const string StripGreyedRetry = "";
    /// <summary>The same strip with the gold RETRY enabled (it carries the app's red overlay box).</summary>
    public const string StripGoldRetry = "";

    /// <summary>The greyed-out RETRY with the game's cursor drawn right over its letters (a 225x48 screenshot).</summary>
    public const string GreyedRetryUnderCursor = "";
}
